import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate, useSearchParams } from 'react-router-dom';
import { MapContainer, TileLayer, CircleMarker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import "./RiverDashboard.css";

const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

// ---------------------------------------------------------
// 📍 COMPONENT 1: Map Popup (Existing)
// ---------------------------------------------------------
const LocationPopup = ({ lat, lon, depth, explanation }) => {
  const [address, setAddress] = useState("Loading address details...");
  const [placeName, setPlaceName] = useState("");

  useEffect(() => {
    const fetchAddress = async () => {
      try {
        const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}`;
        const res = await axios.get(url);
        
        if (res.data && res.data.address) {
          const addr = res.data.address;
          const road = addr.road || "";
          const locality = addr.suburb || addr.neighbourhood || "";
          const area = addr.village || addr.town || addr.city || "";
          const state = addr.state || "";

          const fullAddress = [road, locality, area, state].filter(Boolean).join(", ");
          setAddress(fullAddress || "Address details unavailable");
          setPlaceName(area || "Unknown Location");
        }
      } catch (err) {
        setAddress("Address lookup failed");
      }
    };
    fetchAddress();
  }, [lat, lon]);

  return (
    <div className="popup-content">
      <strong>{placeName || "Flood Point"}</strong>
      <hr style={{margin: '5px 0', border: '0', borderTop: '1px solid #ccc'}}/>
      <div><span className="label">Depth:</span> <span className="val-danger">{depth}m</span></div>
      <div><span className="label">Impact:</span> <span>{explanation}</span></div>
      <div><span className="label">Loc:</span> <span className="val-addr">{address}</span></div>
    </div>
  );
};

// ---------------------------------------------------------
// 📋 COMPONENT 2: Smart List Item (New Feature)
// ---------------------------------------------------------
const AffectedAreaItem = ({ data, rank }) => {
  const [expanded, setExpanded] = useState(false);
  const [fullDetails, setFullDetails] = useState(null);
  const [loadingDetails, setLoadingDetails] = useState(false);

  const toggleDetails = async () => {
    if (!expanded && !fullDetails) {
      setLoadingDetails(true);
      try {
        const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${data.lat}&lon=${data.lon}`;
        const res = await axios.get(url);
        
        if (res.data && res.data.address) {
          const addr = res.data.address;
          setFullDetails({
            road: addr.road || "N/A",
            suburb: addr.suburb || addr.neighbourhood || "N/A",
            village: addr.village || addr.town || "N/A",
            state: addr.state || "N/A",
            formatted: res.data.display_name
          });
        }
      } catch (e) {
        setFullDetails({ error: "Could not fetch address" });
      } finally {
        setLoadingDetails(false);
      }
    }
    setExpanded(!expanded);
  };

  return (
    <div className="area-list-item glass" style={{ marginBottom: '10px', padding: '15px', borderLeft: data.depth > 1.5 ? '4px solid #ef4444' : '4px solid #f59e0b' }}>
      <div className="ali-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', cursor: 'pointer' }} onClick={toggleDetails}>
        <div>
          <span className="ali-rank">#{rank}</span>
          <strong className="ali-place">{data.place || "Unknown Area"}</strong>
          <span className="ali-coords">({data.lat}, {data.lon})</span>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div className="ali-depth" style={{ color: data.depth > 1.5 ? '#ef4444' : '#f59e0b', fontWeight: 'bold', fontSize: '1.2rem' }}>
            {data.depth}m
          </div>
          <small>{data.explanation}</small>
        </div>
      </div>

      {/* Expandable Section for Detailed Address */}
      {expanded && (
        <div className="ali-details" style={{ marginTop: '15px', paddingTop: '10px', borderTop: '1px solid rgba(255,255,255,0.1)', fontSize: '0.9rem' }}>
          {loadingDetails ? (
            <span style={{color:'#fbbf24'}}><i className="fas fa-sync fa-spin"></i> Fetching official address records...</span>
          ) : fullDetails ? (
            <div className="address-grid">
              <p><strong><i className="fas fa-road"></i> Road/Area:</strong> {fullDetails.road}</p>
              <p><strong><i className="fas fa-city"></i> Village/Town:</strong> {fullDetails.village}</p>
              <p><strong><i className="fas fa-map-pin"></i> Suburb:</strong> {fullDetails.suburb}</p>
              <p><strong><i className="fas fa-flag"></i> State:</strong> {fullDetails.state}</p>
            </div>
          ) : (
            <span>Error loading details.</span>
          )}
        </div>
      )}
    </div>
  );
};

// ---------------------------------------------------------
// 🚀 MAIN COMPONENT
// ---------------------------------------------------------
const FloodMap = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [loading, setLoading] = useState(true);
  const [floodData, setFloodData] = useState(null);

  const simulatedLevel = searchParams.get('level');

  useEffect(() => {
    const fetchFloodAnalysis = async () => {
      try {
        setLoading(true);
        const response = await axios.get(`${API_BASE_URL}/api/weather/flood-analysis`, {
          params: { level: simulatedLevel } 
        });
        if (response.data) {
          // SORT DATA: Show deepest floods first
          if (response.data.data) {
            response.data.data.sort((a, b) => b.depth - a.depth);
          }
          setFloodData(response.data);
        }
      } catch (error) {
        console.error("Analysis Failed:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchFloodAnalysis();
  }, [simulatedLevel]);

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Analyzing Satellite Terrain (DEM)...</p></div>;

  const getSeverityColor = (depth) => {
      if (depth < 1.0) return "#f59e0b"; // Orange
      return "#ef4444"; // Red
  };

  return (
    <div className="rd-container">
      <nav className="rd-nav-overlay">
        <div className="rd-wrapper rd-flex-between">
            <div className="rd-brand"><i className="fas fa-water"></i> Periyar<span>Watch</span></div>
            <button onClick={() => navigate('/')} className="nav-btn">
              <i className="fas fa-arrow-left"></i> Dashboard
            </button>
        </div>
      </nav>

      <main className="rd-main-content rd-wrapper" style={{marginTop: '100px'}}>
        
        <div className="rd-hero-text" style={{textAlign: 'center', marginBottom: '40px'}}>
          <h1><i className="fas fa-map-marked-alt"></i> Flood Impact Simulation</h1>
          <p>Visualizing impact at water level: <strong>{floodData?.current_water_level}m</strong></p>
        </div>

        {/* STATS */}
        <div className="rd-stats-grid">
            <div className="rd-card glass">
                <div className="card-head"><span>Simulation Level</span></div>
                <div className="big-stat">{floodData?.current_water_level} m</div>
            </div>
            <div className="rd-card glass">
                <div className="card-head"><span>Affected Households/Spots</span></div>
                <div className="big-stat" style={{color: '#ef4444'}}>{floodData?.flooded_count || 0}</div>
            </div>
        </div>

        {floodData?.data && floodData.data.length > 0 ? (
          <>
            {/* MAP SECTION */}
            <section className="rd-section glass" style={{marginTop: '30px', height: '600px', padding: '10px'}}>
              <MapContainer 
                  center={[10.16, 76.43]} 
                  zoom={13} 
                  style={{ height: "100%", width: "100%", borderRadius: "10px" }}
              >
                  <TileLayer
                      url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                      attribution='&copy; OpenStreetMap contributors'
                  />
                  {floodData.data.map((point, idx) => (
                      <CircleMarker 
                          key={idx}
                          center={[point.lat, point.lon]}
                          radius={6}
                          pathOptions={{ 
                              color: 'white', 
                              weight: 1,
                              fillColor: getSeverityColor(point.depth), 
                              fillOpacity: 0.8 
                          }}
                      >
                          <Popup>
                              <LocationPopup 
                                  lat={point.lat} 
                                  lon={point.lon} 
                                  depth={point.depth} 
                                  explanation={point.explanation} 
                              />
                          </Popup>
                      </CircleMarker>
                  ))}
              </MapContainer>
            </section>

            {/* NEW SECTION: AFFECTED AREAS LIST */}
            <section className="rd-section" style={{ marginTop: '40px' }}>
              <h3 style={{ marginBottom: '20px', display:'flex', alignItems:'center', gap:'10px' }}>
                <i className="fas fa-clipboard-list" style={{ color: '#f59e0b' }}></i> 
                High Priority Rescue Zones (Top 100)
              </h3>
              
              <div className="affected-list-container">
                {floodData.data.slice(0, 100).map((item, index) => (
                  <AffectedAreaItem key={index} data={item} rank={index + 1} />
                ))}
              </div>
              
              {floodData.data.length > 100 && (
                <p style={{textAlign:'center', marginTop:'20px', color:'#94a3b8'}}>
                  + {floodData.data.length - 100} more less critical points hidden for performance.
                </p>
              )}
            </section>
          </>
        ) : (
          <div className="rd-section glass" style={{marginTop: '30px', textAlign:'center', padding:'40px'}}>
            <h3><i className="fas fa-check-circle" style={{color:'#10b981'}}></i> No flood risks detected.</h3>
          </div>
        )}
      </main>
    </div>
  );
};

export default FloodMap;
